-- ============================================================================
-- seed_kenya_questions_batch13.sql
-- 115 EASY questions for the early levels, across all ten categories
-- (Kenyan History, Geography, Wildlife & Culture, Sports, Food & Culture, Swahili & Sheng,
-- Safaricom & Tech, Matatus & Transport, Music & Entertainment, General Knowledge).
-- Each has a "Did you know?" line. Batches 6 to 11 had no easy questions at all.
-- Run AFTER 024_content_quality.sql. Safe to re-run (skips existing question text).
-- Have a Kenyan reviewer check every fact (see batch13_review.md), starting with CHECK first rows.
-- ============================================================================

insert into public.categories (name)
select c.name from (values ($q$General Knowledge$q$), ($q$Kenyan Food & Culture$q$), ($q$Kenyan Geography$q$), ($q$Kenyan History$q$), ($q$Kenyan Sports$q$), ($q$Kenyan Wildlife & Culture$q$), ($q$Matatus & Transport$q$), ($q$Music & Entertainment$q$), ($q$Safaricom & Tech$q$), ($q$Swahili & Sheng$q$)) as c(name)
where not exists (select 1 from public.categories x where x.name = c.name);

insert into public.questions
  (category_id, question_text, option_a, option_b, option_c, option_d, correct_option, difficulty, did_you_know)
select (select id from public.categories where name = v.cat limit 1),
       v.question_text, v.a, v.b, v.c, v.d, v.correct, v.difficulty, v.fact
from (values
  ($q$Kenyan History$q$, $q$Madaraka Day is celebrated on which date?$q$, $q$20 October$q$, $q$1 June$q$, $q$10 October$q$, $q$12 December$q$, 'b', 'easy', $q$On 1 June 1963 Kenya gained internal self-rule, six months before independence.$q$),
  ($q$Kenyan History$q$, $q$Mashujaa Day, which honours Kenya's heroes, is celebrated on which date?$q$, $q$20 October$q$, $q$12 December$q$, $q$10 October$q$, $q$1 June$q$, 'a', 'easy', $q$It used to be called Kenyatta Day. Mashujaa means heroes.$q$),
  ($q$Kenyan History$q$, $q$Kenya gained its independence in 1963 from which country?$q$, $q$Portugal$q$, $q$Britain$q$, $q$Germany$q$, $q$France$q$, 'b', 'easy', $q$Kenya had been under British rule since the late 1800s.$q$),
  ($q$Kenyan History$q$, $q$The Mau Mau fighters of the 1950s rose up against which rule?$q$, $q$British colonial rule$q$, $q$Arab rule$q$, $q$Portuguese rule$q$, $q$German rule$q$, 'a', 'easy', $q$The Mau Mau uprising lasted from 1952 to 1960.$q$),
  ($q$Kenyan History$q$, $q$Which Kenyan woman won the Nobel Peace Prize in 2004?$q$, $q$Wangari Maathai$q$, $q$Lupita Nyong'o$q$, $q$Charity Ngilu$q$, $q$Grace Ogot$q$, 'a', 'easy', $q$She founded the Green Belt Movement, which has planted millions of trees.$q$),
  ($q$Kenyan History$q$, $q$Dedan Kimathi is remembered as a leader of which movement?$q$, $q$The Giriama Union$q$, $q$The Mau Mau$q$, $q$The Maasai Council$q$, $q$The Mijikenda$q$, 'b', 'easy', $q$He was captured in 1956 and executed in 1957.$q$),
  ($q$Kenyan History$q$, $q$In which city is Fort Jesus, the old fort built by the Portuguese?$q$, $q$Nairobi$q$, $q$Nakuru$q$, $q$Mombasa$q$, $q$Kisumu$q$, 'c', 'easy', $q$Fort Jesus was built in the 1590s and is now a World Heritage Site.$q$),
  ($q$Kenyan History$q$, $q$Which Kenyan city began as a railway depot in 1899?$q$, $q$Kisumu$q$, $q$Mombasa$q$, $q$Nairobi$q$, $q$Eldoret$q$, 'c', 'easy', $q$Nairobi grew from a camp on the Uganda Railway into the capital.$q$),
  ($q$Kenyan History$q$, $q$Which president ruled Kenya from 1978 to 2002?$q$, $q$Jomo Kenyatta$q$, $q$Uhuru Kenyatta$q$, $q$Daniel arap Moi$q$, $q$Mwai Kibaki$q$, 'c', 'easy', $q$Moi took over when Jomo Kenyatta died in 1978.$q$),
  ($q$Kenyan Geography$q$, $q$Which imaginary line crosses Kenya near the town of Nanyuki?$q$, $q$The Prime Meridian$q$, $q$The Tropic of Capricorn$q$, $q$The Tropic of Cancer$q$, $q$The Equator$q$, 'd', 'easy', $q$Tourists often stop at the Equator signs to take photos.$q$),
  ($q$Kenyan Geography$q$, $q$Lake Victoria is shared by Kenya, Uganda and which other country?$q$, $q$Tanzania$q$, $q$Rwanda$q$, $q$Ethiopia$q$, $q$Somalia$q$, 'a', 'easy', $q$It is the largest lake in Africa.$q$),
  ($q$Kenyan Geography$q$, $q$Which is the largest lake that lies entirely inside Kenya?$q$, $q$Lake Nakuru$q$, $q$Lake Turkana$q$, $q$Lake Naivasha$q$, $q$Lake Baringo$q$, 'b', 'easy', $q$Lake Turkana is nicknamed the Jade Sea.$q$),
  ($q$Kenyan Geography$q$, $q$Which city is Kenya's second largest?$q$, $q$Nakuru$q$, $q$Eldoret$q$, $q$Mombasa$q$, $q$Kisumu$q$, 'c', 'easy', $q$Mombasa is on the coast and has Kenya's main seaport.$q$),
  ($q$Kenyan Geography$q$, $q$Which of these countries does NOT border Kenya?$q$, $q$Tanzania$q$, $q$Uganda$q$, $q$Ethiopia$q$, $q$Rwanda$q$, 'd', 'easy', $q$Kenya also borders Somalia and South Sudan.$q$),
  ($q$Kenyan Geography$q$, $q$Which ocean lies along Kenya's coast?$q$, $q$The Pacific Ocean$q$, $q$The Arctic Ocean$q$, $q$The Indian Ocean$q$, $q$The Atlantic Ocean$q$, 'c', 'easy', $q$Mombasa, Malindi and Lamu are all on the Indian Ocean.$q$),
  ($q$Kenyan Geography$q$, $q$Mount Kilimanjaro, seen from Amboseli, is in which country?$q$, $q$Uganda$q$, $q$Kenya$q$, $q$Tanzania$q$, $q$Ethiopia$q$, 'c', 'easy', $q$At 5,895 metres it is the highest mountain in Africa.$q$),
  ($q$Kenyan Geography$q$, $q$Which Kenyan city stands on the shore of Lake Victoria?$q$, $q$Nakuru$q$, $q$Eldoret$q$, $q$Nyeri$q$, $q$Kisumu$q$, 'd', 'easy', $q$Kisumu is often called the Lake City.$q$),
  ($q$Kenyan Geography$q$, $q$Where does Mount Kenya rank among Africa's mountains by height?$q$, $q$Third highest$q$, $q$Second highest$q$, $q$Fifth highest$q$, $q$Highest$q$, 'b', 'easy', $q$Only Mount Kilimanjaro is taller.$q$),
  ($q$Kenyan Geography$q$, $q$Which country lies directly south of Kenya?$q$, $q$Ethiopia$q$, $q$Somalia$q$, $q$Tanzania$q$, $q$Uganda$q$, 'c', 'easy', $q$Mount Kilimanjaro is just across the border.$q$),
  ($q$Kenyan Geography$q$, $q$Which desert lies in northern Kenya?$q$, $q$The Namib$q$, $q$The Kalahari$q$, $q$The Sahara$q$, $q$The Chalbi Desert$q$, 'd', 'easy', $q$The Chalbi Desert is in Marsabit County and is one of the hottest places in Kenya.$q$),
  ($q$Kenyan Wildlife & Culture$q$, $q$Which of these animals is NOT one of Africa's Big Five?$q$, $q$Giraffe$q$, $q$Lion$q$, $q$Elephant$q$, $q$Buffalo$q$, 'a', 'easy', $q$The Big Five are the lion, leopard, buffalo, elephant and rhino.$q$),
  ($q$Kenyan Wildlife & Culture$q$, $q$Which river do the wildebeest famously cross in the Maasai Mara?$q$, $q$The Athi River$q$, $q$The Mara River$q$, $q$The Tana River$q$, $q$The Nile$q$, 'b', 'easy', $q$Crocodiles wait in the water for the herds to cross.$q$),
  ($q$Kenyan Wildlife & Culture$q$, $q$Which is the tallest animal in the world?$q$, $q$The giraffe$q$, $q$The hippo$q$, $q$The rhino$q$, $q$The elephant$q$, 'a', 'easy', $q$A giraffe can grow taller than five metres.$q$),
  ($q$Kenyan Wildlife & Culture$q$, $q$Which animal is the fastest on land?$q$, $q$The lion$q$, $q$The cheetah$q$, $q$The zebra$q$, $q$The leopard$q$, 'b', 'easy', $q$A cheetah can reach about 100 kilometres an hour in a short sprint.$q$),
