  ($q$Kenyan Wildlife & Culture$q$, $q$Lake Nakuru National Park is famous for which pink birds?$q$, $q$Pelicans$q$, $q$Flamingos$q$, $q$Storks$q$, $q$Ostriches$q$, 'b', 'easy', $q$Flamingos feed on tiny algae in the shallow lake.$q$),
  ($q$Kenyan Wildlife & Culture$q$, $q$Which colour of cloth, called a shuka, is most strongly linked to the Maasai?$q$, $q$Purple$q$, $q$White$q$, $q$Red$q$, $q$Yellow$q$, 'c', 'easy', $q$Shukas come in many colours, but red is the best known.$q$),
  ($q$Kenyan Sports$q$, $q$Kenya is world famous for producing champions in which sport?$q$, $q$Swimming$q$, $q$Gymnastics$q$, $q$Ice hockey$q$, $q$Long-distance running$q$, 'd', 'easy', $q$Many of the world's best marathon and track runners are Kenyan.$q$),
  ($q$Kenyan Sports$q$, $q$The Safari Rally is a famous Kenyan event in which sport?$q$, $q$Cycling$q$, $q$Rowing$q$, $q$Horse racing$q$, $q$Motor rallying$q$, 'd', 'easy', $q$Cars race over rough roads and tracks, often through mud and dust.$q$),
  ($q$Kenyan Sports$q$, $q$How many players from one team are on the pitch in a football match?$q$, $q$11$q$, $q$9$q$, $q$12$q$, $q$10$q$, 'a', 'easy', $q$Each team has 11 players, including the goalkeeper.$q$),
  ($q$Kenyan Sports$q$, $q$How long is a marathon?$q$, $q$100 kilometres$q$, $q$42.195 kilometres$q$, $q$21 kilometres$q$, $q$10 kilometres$q$, 'b', 'easy', $q$Marathon distances come from the legend of a Greek messenger.$q$),
  ($q$Kenyan Sports$q$, $q$Kenya's Shujaa team plays which sport?$q$, $q$Basketball$q$, $q$Volleyball$q$, $q$Cricket$q$, $q$Rugby sevens$q$, 'd', 'easy', $q$Shujaa won the 2016 Singapore Sevens, Kenya's biggest title in the sport.$q$),
  ($q$Kenyan Sports$q$, $q$In rugby union, how many points is a try worth?$q$, $q$5$q$, $q$3$q$, $q$2$q$, $q$7$q$, 'a', 'easy', $q$A conversion kick after the try adds two more points.$q$),
  ($q$General Knowledge$q$, $q$Who painted the Mona Lisa?$q$, $q$Vincent van Gogh$q$, $q$Pablo Picasso$q$, $q$Leonardo da Vinci$q$, $q$Michelangelo$q$, 'c', 'easy', $q$The painting hangs in the Louvre museum in Paris.$q$),
